(function(root){'use strict';
function number(v,label,min=0,max=1e9){if(v===''||v==null||typeof v==='boolean')throw Error(label+': valor ausente');const n=typeof v==='number'?v:Number(String(v).replace(',','.'));if(!Number.isFinite(n)||n<min||n>max)throw Error(label+': valor inválido');return n}
function flag(v,label){return number(v,label,0,1)===1?true:(Number(v)===0?false:(()=>{throw Error(label+': use 0 ou 1')})())}
function text(v,label){if(typeof v!=='string'||!v.trim()||v.length>2000)throw Error(label+': texto inválido');return v.trim()}
function records(table,name,cols){if(!Array.isArray(table)||table.length<2||table.length>10000)throw Error('Aba '+name+' ausente ou vazia');const h=table[0];for(const c of cols)if(!h.includes(c))throw Error(name+': coluna '+c+' ausente');return table.slice(1).filter(r=>r.some(v=>v!==''&&v!=null)).map(row=>Object.fromEntries(h.map((key,i)=>[key,row[i]])))}
function compile(payload){if(!payload||payload.version!==1||!payload.sheets)throw Error('Arquivo deve conter version=1 e sheets');const s=payload.sheets;
const refRows=records(s.Referencia,'Referencia',['faixa','limite_superior_mw','teif_pct','ip_pct']);if(refRows.length!==5)throw Error('São necessárias cinco faixas');const refs=refRows.map((r,k)=>{if(number(r.faixa,'faixa')!==k+1)throw Error('Faixas fora de ordem');return [number(r.limite_superior_mw,'limite',.000001,1300),number(r.teif_pct,'TEIF',0,100),number(r.ip_pct,'IP',0,100)]});if(refs.some((r,i)=>i&&r[0]<=refs[i-1][0])||refs[4][0]!==1300)throw Error('Limites devem crescer e terminar em 1300 MW');
const params=Object.create(null);for(const r of records(s.Parametros,'Parametros',['chave','valor'])){let k=text(r.chave,'chave');if(Object.hasOwn(params,k))throw Error('Parâmetro duplicado: '+k);params[k]=r.valor}
const settings={year:number(params.ano_cenario,'ano_cenario',2000,2100),study:text(params.titulo_estudo,'titulo_estudo'),notes:text(params.hipotese,'hipotese'),participation:flag(params.incluir_participacao,'incluir_participacao'),date:text(params.data_consulta,'data_consulta'),colors:{}};if(!Number.isInteger(settings.year))throw Error('Ano deve ser inteiro');for(const k of ['azul_escuro','azul_medio','azul_claro','verde','amarelo']){const v=text(params[k],k);if(!/^#[0-9a-f]{6}$/i.test(v))throw Error('Cor inválida: '+k);settings.colors[k]=v}
const seenUnits=new Set();const units=records(s.UGs,'UGs',['unidade_id','usina_id','usina','ug','potencia_mw','elegivel','participacao','motivo']).map(r=>{let id=text(r.unidade_id,'unidade_id');if(seenUnits.has(id))throw Error('UG duplicada: '+id);seenUnits.add(id);return {id,plantId:text(r.usina_id,'usina_id'),plant:text(r.usina,'usina'),ug:text(r.ug,'ug'),mw:number(r.potencia_mw,'potencia_mw',.000001,1300),eligible:flag(r.elegivel,'elegivel'),optional:flag(r.participacao,'participacao'),reason:text(r.motivo,'motivo')}});
const seen=new Set();const plants=records(s.Usinas,'Usinas',['id','nome','ons_nome','ceg','grupo','mes_base','teif_pct','ip_pct','incluir_padrao','fonte']).map(r=>{const id=text(r.id,'id');if(!/^[A-Z0-9_-]+$/.test(id)||seen.has(id))throw Error('ID de usina inválido ou duplicado: '+id);seen.add(id);if(!['operada','participacao'].includes(r.grupo))throw Error('Grupo inválido: '+id);const u=units.filter(u=>u.plantId===id&&u.eligible);if(!u.length)throw Error(id+': nenhuma UG elegível');if(u.some(u=>u.optional!==(r.grupo==='participacao')))throw Error(id+': participação inconsistente entre abas');const bands=u.map(u=>refs.findIndex(r=>u.mw<=r[0]));if(new Set(bands).size!==1)throw Error(id+': UGs em faixas distintas; separe os conjuntos e suas taxas antes de incluir');let source=text(r.fonte,'fonte');if(new URL(source).protocol!=='https:')throw Error('Fonte deve usar HTTPS');return {id,name:text(r.nome,'nome'),onsName:text(r.ons_nome,'ons_nome'),ceg:text(r.ceg,'ceg'),kind:r.grupo,month:text(r.mes_base,'mes_base'),teif:number(r.teif_pct,'teif_pct',0,100),ip:number(r.ip_pct,'ip_pct',0,100),includeDefault:flag(r.incluir_padrao,'incluir_padrao'),source,n:u.length,power:Number(u.reduce((sum,x)=>sum+x.mw,0).toFixed(8)),unitMw:u[0].mw,unitPowerLabel:[...new Set(u.map(x=>x.mw))].join(' / '),unitIds:u.map(x=>x.ug),configurationSource:'Planilha Google Sheets',configurationVersion:'sheets-v1'}});
for(const u of units)if(u.eligible&&!seen.has(u.plantId))throw Error('UG elegível sem taxas em Usinas: '+u.id);
return {plants,units,refs,settings};}
const api={compile};root.ConfigModel=api;if(typeof module!=='undefined')module.exports=api;
})(globalThis);
